function ProductInfo({p,info}:{p:Product;info?:ProductInfoSettings}){const s={...infoDefaults,...info};const rows=[s.showName&&p.name,s.showSku&&p.sku&&`SKU ${p.sku}`,s.showPrice&&`${s.pricePrefix||'₺'}${p.price.toLocaleString('tr-TR',{minimumFractionDigits:2})}`,s.showMaterial&&p.material,s.showCategory&&p.category,s.showDescription&&p.description.replace(/<[^>]+>/g,' ').slice(0,100)].filter(Boolean);return <div style={{fontFamily:s.fontFamily,fontSize:s.fontSize,color:s.color,textAlign:s.align,lineHeight:1.2}}>{rows.map((x,i)=><div key={i}>{x}</div>)}</div>}
function EditorCanvas({page,products,catalogSettings,selectedBlockId,onSelect,onDrag,onResize,onPatch,grid}:{page:Page;products:Product[];catalogSettings:CatalogSettings;selectedBlockId?:string|null;onSelect:(id:string|null)=>void;onDrag:(id:string,e:React.PointerEvent)=>void;onResize:(id:string,e:React.PointerEvent)=>void;onPatch:(id:string,p:Partial<PageBlock>)=>void;grid:boolean}){const[qr,setQr]=React.useState<Record<string,string>>({});React.useEffect(()=>{(async()=>{const out:Record<string,string>={};for(const b of page.content.blocks||[])if(b.showQr&&b.linkUrl)try{out[b.id]=await QRCode.toDataURL(b.linkUrl,{width:120,margin:1})}catch{}setQr(out)})()},[page.content.blocks]);const s={...defaults,...catalogSettings};const header=page.style?.showHeader??s.showHeader,footer=page.style?.showFooter??s.showFooter;return <div className="relative w-full h-full overflow-hidden" style={{backgroundColor:page.style?.backgroundColor||s.backgroundColor,backgroundImage:page.style?.backgroundImage?`url(${page.style.backgroundImage})`:undefined,backgroundSize:'cover',backgroundPosition:'center',color:page.style?.textColor||'#0f203a'}}>{grid&&<div className="absolute inset-0 pointer-events-none opacity-40" style={{backgroundImage:'linear-gradient(rgba(15,32,58,.10) 1px,transparent 1px),linear-gradient(90deg,rgba(15,32,58,.10) 1px,transparent 1px)',backgroundSize:'5% 5%'}}/>}{header&&<div className="absolute z-[100] left-[3%] right-[3%] top-[2%] border-b border-[#0f203a]/25 pb-1 text-[7px] uppercase tracking-[.18em]">{page.style?.headerText||s.headerText}</div>}{footer&&<div className="absolute z-[100] left-[3%] right-[3%] bottom-[2%] pt-1 border-t border-[#0f203a]/20 text-[7px] flex justify-between"><span>{page.style?.footerText||s.footerText}</span><span>{(page.style?.showPageNumber??s.footerPageNumbers)?String(page.order+1).padStart(2,'0'):''}</span></div>}{(page.content.blocks||[]).map(b=>{const selected=selectedBlockId===b.id,p=b.productId?products.find(x=>x.id===b.productId):undefined,base={position:'absolute' as const,left:`${b.x??8}%`,top:`${b.y??8}%`,width:`${b.width??30}%`,height:`${b.height??25}%`,zIndex:b.zIndex??20};if(b.type==='text')return <div key={b.id} className={cn('p-2 flex items-center cursor-move',selected?'ring-2 ring-[#0f203a] ring-offset-2':'')} style={{...base,fontFamily:b.fontFamily||'Georgia, serif',fontSize:b.fontSize||24,fontWeight:b.fontWeight||400,fontStyle:b.fontStyle||'italic',textAlign:b.textAlign||'left',color:b.textColor||'#0f203a'}} onPointerDown={e=>{e.stopPropagation();onSelect(b.id);onDrag(b.id,e)}}><div contentEditable suppressContentEditableWarning className="w-full outline-none" onPointerDown={e=>e.stopPropagation()} onBlur={e=>onPatch(b.id,{alt:e.currentTarget.textContent||''})}>{b.alt||'Metin ekle'}</div>{selected&&<button onPointerDown={e=>{e.stopPropagation();onResize(b.id,e)}} className="absolute -right-1 -bottom-1 w-3 h-3 bg-[#0f203a] rounded-sm"/>}</div>;if(b.type==='frame'||b.type==='image'){const isProduct=b.type==='frame'&&b.frameKind==='product',src=isProduct?p?.images?.[0]:b.url,scale=b.imageScale||1;return <div key={b.id} className={cn('overflow-hidden bg-[#f4f5f7] cursor-move',selected?'ring-2 ring-[#0f203a] ring-offset-2':'')} style={{...base,border:b.type==='frame'?`${b.borderWidth??1}px solid rgba(15,32,58,.3)`:'none',borderRadius:b.borderRadius||0}} onPointerDown={e=>{e.stopPropagation();onSelect(b.id);onDrag(b.id,e)}} onDoubleClick={e=>{e.stopPropagation();onSelect(b.id);onPatch(b.id,{imageScale:clamp(scale+.25,.5,3)})}}>{src?<img src={src} draggable={false} className="w-full h-full" style={{objectFit:b.objectFit||'contain',transform:`scale(${scale})`,objectPosition:`${b.imagePositionX??50}% ${b.imagePositionY??50}%`}}/>:<div className="w-full h-full flex items-center justify-center text-[8px] uppercase tracking-[.18em] text-[#0f203a]/35">{isProduct?'Ürün eklemek için tıkla':'Görsel eklemek için tıkla'}</div>}{isProduct&&p&&<div className="absolute bottom-0 left-0 right-0 bg-white/92 p-1.5"><ProductInfo p={p} info={b.productInfo}/></div>}{qr[b.id]&&<img src={qr[b.id]} className="absolute right-1 bottom-1 w-10 h-10 bg-white p-1"/>}{selected&&<button onPointerDown={e=>{e.stopPropagation();onResize(b.id,e)}} className="absolute -right-1 -bottom-1 w-3 h-3 bg-[#0f203a] rounded-sm"/>}</div>}return null})}{!(page.content.blocks||[]).length&&<div className="absolute inset-0 flex items-center justify-center text-[#0f203a]/25 font-serif italic text-3xl">Layout seçiniz</div>}</div>}
export function CatalogStudioFinal({catalog,pages,products,collections=[],categories=[],onUpdatePage,onUpdateCatalog,onAddPage,onDeletePage,onDuplicatePage,onReplacePages,onExit,canPublish=true,onPublish,onPreview}:Props){const sorted=[...pages].sort((a,b)=>a.order-b.order);const[pageId,setPageId]=React.useState(sorted[0]?.id||null);React.useEffect(()=>{if(!sorted.some(p=>p.id===pageId))setPageId(sorted[0]?.id||null)},[pages]);const page=sorted.find(p=>p.id===pageId);const[panel,setPanel]=React.useState<'catalog'|'layout'|'element'|'products'>('catalog');const[blockId,setBlockId]=React.useState<string|null>(null);const[grid,setGrid]=React.useState(false);const[history,setHistory]=React.useState<{pages:Page[];catalog:Catalog}[]>([]);const[future,setFuture]=React.useState<{pages:Page[];catalog:Catalog}[]>([]);const[busy,setBusy]=React.useState(false);const drag=React.useRef<any>(null);const canvas=React.useRef<HTMLDivElement>(null);const settings={...defaults,...catalog.settings};const snap=()=>({pages:pages.map(p=>({...p,content:{...p.content,blocks:p.content.blocks?.map(b=>({...b,productInfo:b.productInfo?{...b.productInfo}:undefined}))}})),catalog:{...catalog,settings:{...settings}}});const commitPage=(next:Page)=>{setHistory(h=>[...h.slice(-30),snap()]);setFuture([]);onUpdatePage(next)};const commitCatalog=(u:Partial<Catalog>)=>{setHistory(h=>[...h.slice(-30),snap()]);setFuture([]);onUpdateCatalog(u)};const patchBlock=(id:string,p:Partial<PageBlock>)=>page&&commitPage({...page,content:{...page.content,blocks:(page.content.blocks||[]).map(b=>b.id===id?{...b,...p}:b)}});const addBlock=(kind:'product'|'image'|'text')=>{if(!page)return;const id=crypto.randomUUID();const b=kind==='product'?productFrame(id,10,10,25,30):kind==='image'?imageFrame(id,10,10,35,40):textBlock(id,'Yeni metin',10,10,35,12,{fontSize:24});commitPage({...page,content:{...page.content,blocks:[...(page.content.blocks||[]),b]}});setBlockId(id);setPanel('element')};const applyLayout=(id:LayoutId)=>{if(!page)return;const ids=page.content.productIds||[];commitPage({...page,layoutId:id,content:{...page.content,blocks:adaptiveBlocks(id,ids),headline:page.content.headline||'NEW COLLECTION',subheadline:page.content.subheadline||'VENTA JEWELRY · DIGITAL COLLECTION',body:page.content.body||'A premium interactive catalog'}});setBlockId(null);setPanel('layout')};const startDrag=(id:string,e:React.PointerEvent)=>{if(!canvas.current)return;const b=page?.content.blocks?.find(x=>x.id===id);if(!b)return;drag.current={id,sx:e.clientX,sy:e.clientY,x:b.x||8,y:b.y||8}};React.useEffect(()=>{const move=(e:PointerEvent)=>{const d=drag.current;if(!d||!page||!canvas.current)return;const r=canvas.current.getBoundingClientRect(),dx=(e.clientX-d.sx)/r.width*100,dy=(e.clientY-d.sy)/r.height*100,b=page.content.blocks?.find(x=>x.id===d.id);if(!b)return;onUpdatePage({...page,content:{...page.content,blocks:(page.content.blocks||[]).map(x=>x.id===d.id?{...x,x:clamp(d.x+dx,0,100-(x.width||30)),y:clamp(d.y+dy,0,100-(x.height||25))}:x)}})};const up=()=>drag.current=null;window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);return()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up)}},[page]);const resize=(id:string,e:React.PointerEvent)=>{if(!canvas.current||!page)return;const b=page.content.blocks?.find(x=>x.id===id);if(!b)return;const sx=e.clientX,sy=e.clientY,w=b.width||30,h=b.height||25;const move=(ev:PointerEvent)=>{const r=canvas.current!.getBoundingClientRect(),dx=(ev.clientX-sx)/r.width*100,dy=(ev.clientY-sy)/r.height*100;onUpdatePage({...page,content:{...page.content,blocks:(page.content.blocks||[]).map(x=>x.id===id?{...x,width:clamp(w+dx,5,100-(x.x||0)),height:clamp(h+dy,5,100-(x.y||0))}:x)}})};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)};const undo=()=>{const s=history.at(-1);if(!s)return;setFuture(f=>[...f,snap()]);setHistory(h=>h.slice(0,-1));if(onReplacePages)onReplacePages(s.pages);else s.pages.forEach(onUpdatePage);onUpdateCatalog(s.catalog)};const redo=()=>{const s=future.at(-1);if(!s)return;setHistory(h=>[...h,snap()]);setFuture(f=>f.slice(0,-1));if(onReplacePages)onReplacePages(s.pages);else s.pages.forEach(onUpdatePage);onUpdateCatalog(s.catalog)};const duplicate=()=>page&&onDuplicatePage?onDuplicatePage(page.id):onAddPage();const movePage=(dir:number)=>{if(!page)return;const i=sorted.findIndex(x=>x.id===page.id),j=i+dir;if(j<0||j>=sorted.length)return;const a=sorted[i],b=sorted[j];onUpdatePage({...a,order:b.order});onUpdatePage({...b,order:a.order})};const publish=async()=>{if(!onPublish)return;setBusy(true);try{await onPublish()}finally{setBusy(false)}};return <div className="flex h-screen bg-[#e9edf2] text-[#0f203a] select-none"><aside className="w-64 bg-white border-r flex flex-col"><div className="h-16 px-4 border-b flex items-center justify-between"><button onClick={onExit} className="p-2"><ArrowLeft size={18}/></button><Label className="mb-0">Studio</Label><button disabled={!canPublish} onClick={onAddPage} className="p-2"><Plus size={18}/></button></div><div className="p-3 border-b flex gap-1"><button onClick={undo} disabled={!history.length} className="p-2 border rounded disabled:opacity-25"><Undo2 size={14}/></button><button onClick={redo} disabled={!future.length} className="p-2 border rounded disabled:opacity-25"><Redo2 size={14}/></button><button disabled={!page||!canPublish} onClick={duplicate} className="p-2 border rounded disabled:opacity-25"><Copy size={14}/></button></div><div className="flex-1 overflow-y-auto p-3 space-y-2">{sorted.map((p,i)=><div key={p.id} onClick={()=>{setPageId(p.id);setBlockId(null);setPanel('catalog')}} className={cn('p-2 border cursor-pointer',pageId===p.id?'border-[#0f203a] bg-white shadow-sm':'border-transparent')}><div className="flex gap-2 items-center"><span className="text-[9px] opacity-40">{String(i+1).padStart(2,'0')}</span><span className="text-[10px] truncate flex-1">{p.title}</span></div><div className="mt-2 aspect-[1.6] bg-[#f3f5f7] overflow-hidden"><PageRenderer page={p} products={products} thumbnail catalogSettings={settings}/></div><div className="flex justify-between mt-1"><button onClick={e=>{e.stopPropagation();movePage(-1)}}><ArrowUp size={11}/></button><button onClick={e=>{e.stopPropagation();movePage(1)}}><ArrowDown size={11}/></button><button disabled={!canPublish} onClick={e=>{e.stopPropagation();onDeletePage(p.id)}} className="text-red-500"><Trash2 size={11}/></button></div></div>)}</div></aside><main className="flex-1 flex flex-col"><header className="h-16 bg-white border-b px-5 flex justify-between items-center"><div className="flex items-center gap-3"><b className="text-sm">{catalog.name}</b><span className="text-[9px] px-2 py-1 bg-[#f1f4f7] rounded">{page?`${sorted.findIndex(x=>x.id===page.id)+1}/${sorted.length}`:'—'}</span></div><div className="flex gap-2"><button onClick={onExit} className="px-3 py-2 border rounded text-xs"><ArrowLeft size={13} className="inline mr-1"/>Panele dön</button><button onClick={onPreview} className="px-4 py-2 border rounded text-xs"><Eye size={14} className="inline mr-1"/>Önizle</button>{canPublish&&<button onClick={publish} disabled={busy} className="px-5 py-2 bg-[#0f203a] text-white rounded text-xs">{busy?'Yayınlanıyor…':'Yayınla'}</button>}</div></header><div className="flex-1 overflow-auto p-8 flex justify-center items-start"><div ref={canvas} className="relative bg-white shadow-2xl overflow-hidden" style={{width:'min(820px,75vw)',aspectRatio:`${settings.pageWidth}/${settings.pageHeight}`}} onPointerDown={()=>setBlockId(null)}>{page&&<EditorCanvas page={page} products={products} catalogSettings={settings} selectedBlockId={blockId} onSelect={id=>{setBlockId(id);if(id)setPanel('element')}} onDrag={startDrag} onResize={resize} onPatch={patchBlock} grid={grid}/>}</div></div></main><aside className="w-[430px] bg-white border-l overflow-y-auto"><nav className="sticky top-0 z-50 bg-white border-b p-2 grid grid-cols-4 gap-1"><Tab icon={<Ruler size={14}/>} text="Katalog" active={panel==='catalog'} onClick={()=>setPanel('catalog')}/><Tab icon={<LayoutTemplate size={14}/>} text="Layout" active={panel==='layout'} onClick={()=>setPanel('layout')}/><Tab icon={<Move size={14}/>} text="Eleman" active={panel==='element'} onClick={()=>setPanel('element')} disabled={!blockId}/><Tab icon={<Package size={14}/>} text="Ürünler" active={panel==='products'} onClick={()=>setPanel('products')}/></nav>{panel==='catalog'&&<CatalogPanel page={page} catalog={catalog} canEdit={canPublish} onUpdatePage={commitPage} onUpdateCatalog={commitCatalog} grid={grid} setGrid={setGrid} onAddBlock={addBlock}/>} {panel==='layout'&&page&&<LayoutPanel page={page} onApply={applyLayout}/>} {panel==='element'&&page&&<ElementPanel page={page} blockId={blockId} products={products} canEdit={canPublish} onPatch={p=>patchBlock(blockId!,p)} onRemove={id=>{commitPage({...page,content:{...page.content,blocks:(page.content.blocks||[]).filter(b=>b.id!==id)}});setBlockId(null);setPanel('layout')}} onUpload={async f=>patchBlock(blockId!,{url:await upload(f,'block')})} onAddBlock={addBlock}/>} {panel==='products'&&page&&<ProductsPanel page={page} products={products} collections={collections} categories={categories} onUpdate={p=>commitPage(p)}/>}</aside></div>}
function CatalogPanel({page,catalog,canEdit,onUpdatePage,onUpdateCatalog,grid,setGrid,onAddBlock}:{page?:Page;catalog:Catalog;canEdit:boolean;onUpdatePage:(p:Page)=>void;onUpdateCatalog:(u:Partial<Catalog>)=>void;grid:boolean;setGrid:(v:boolean)=>void;onAddBlock:(k:'product'|'image'|'text')=>void}){const s={...defaults,...catalog.settings};const[draft,setDraft]=React.useState({w:s.pageWidth,h:s.pageHeight,unit:s.unit});React.useEffect(()=>setDraft({w:s.pageWidth,h:s.pageHeight,unit:s.unit}),[s.pageWidth,s.pageHeight,s.unit]);const set=(x:Partial<CatalogSettings>)=>onUpdateCatalog({settings:{...s,...x}});const apply=()=>set({pageWidth:Number(draft.w),pageHeight:Number(draft.h),unit:draft.unit});const pageStyle=(x:any)=>page&&onUpdatePage({...page,style:{...page.style,...x}});const file=async(e:React.ChangeEvent<HTMLInputElement>,kind:'logo'|'page')=>{const f=e.target.files?.[0];if(!f)return;try{const url=await upload(f,kind);if(kind==='logo')onUpdateCatalog({logoUrl:url});else pageStyle({backgroundImage:url})}catch(err:any){alert(err.message)}e.target.value=''};return <div className="p-5"><Section title="Katalog giriş ve marka"><Field disabled={!canEdit} value={catalog.name} onChange={e=>onUpdateCatalog({name:e.target.value})} placeholder="Katalog adı"/><div className="flex gap-2 mt-2"><label className="smallbtn flex-1 cursor-pointer"><UploadCloud size={13}/> Logo seçiniz<input disabled={!canEdit} type="file" accept="image/*" className="hidden" onChange={e=>file(e,'logo')}/></label>{catalog.logoUrl&&<img src={catalog.logoUrl} className="w-12 h-9 object-contain border"/>}</div><Field disabled={!canEdit} value={catalog.description||''} onChange={e=>onUpdateCatalog({description:e.target.value})} placeholder="Giriş sayfası açıklaması"/></Section><Section title="Katalog arka planı"><div className="grid grid-cols-2 gap-2"><label className="smallbox">Renk<input disabled={!canEdit} type="color" value={s.backgroundColor} onChange={e=>set({backgroundColor:e.target.value})}/></label><label className="smallbox cursor-pointer">Görsel<input disabled={!canEdit} type="file" accept="image/*" className="hidden" onChange={e=>file(e,'page')}/><span>Görsel seçiniz</span></label></div></Section><Section title="Katalog ebatı"><div className="grid grid-cols-3 gap-2"><Field disabled={!canEdit} type="number" value={draft.w} onChange={e=>setDraft(d=>({...d,w:e.target.value}))}/><Field disabled={!canEdit} type="number" value={draft.h} onChange={e=>setDraft(d=>({...d,h:e.target.value}))}/><select disabled={!canEdit} className="field" value={draft.unit} onChange={e=>setDraft(d=>({...d,unit:e.target.value as any}))}><option value="mm">mm</option><option value="px">px</option><option value="in">in</option></select></div><div className="grid grid-cols-4 gap-1 mt-2">{[[210,297,'A4'],[148,210,'A5'],[210,210,'Kare'],[297,210,'A4 Yatay']].map(([w,h,n])=><button key={String(n)} disabled={!canEdit} className="smallbtn" onClick={()=>setDraft({w:w as number,h:h as number,unit:'mm'})}>{n as string}</button>)}</div><button disabled={!canEdit} onClick={apply} className="w-full mt-2 py-2 bg-[#0f203a] text-white rounded text-[9px]">UYGULA</button></Section><Section title="Sayfa taslağı"><label className="flex gap-2 text-[9px]"><input disabled={!canEdit} type="checkbox" checked={s.showHeader} onChange={e=>set({showHeader:e.target.checked})}/> Üst bilgi çizgisi</label><Field disabled={!canEdit} value={s.headerText} onChange={e=>set({headerText:e.target.value})} placeholder="Üst bilgi metni"/><label className="flex gap-2 text-[9px] mt-2"><input disabled={!canEdit} type="checkbox" checked={s.showPageNumbers} onChange={e=>set({showPageNumbers:e.target.checked})}/> Üst bilgi numaratörü</label><label className="flex gap-2 text-[9px] mt-2"><input disabled={!canEdit} type="checkbox" checked={s.showFooter} onChange={e=>set({showFooter:e.target.checked})}/> Alt bilgi alanı</label><Field disabled={!canEdit} value={s.footerText} onChange={e=>set({footerText:e.target.value})} placeholder="Alt bilgi metni"/><label className="flex gap-2 text-[9px] mt-2"><input disabled={!canEdit} type="checkbox" checked={s.footerPageNumbers} onChange={e=>set({footerPageNumbers:e.target.checked})}/> Alt bilgi numaratörü</label><select disabled={!canEdit} value={s.pageNumberPosition} onChange={e=>set({pageNumberPosition:e.target.value as any})} className="field mt-2"><option value="top-left">Üst sol</option><option value="top-center">Üst orta</option><option value="top-right">Üst sağ</option><option value="bottom-left">Alt sol</option><option value="bottom-center">Alt orta</option><option value="bottom-right">Alt sağ</option></select></Section>{page&&<Section title="Seçili sayfa özel ayarları"><Field disabled={!canEdit} value={page.title} onChange={e=>onUpdatePage({...page,title:e.target.value})} placeholder="Sayfa adı"/><Field disabled={!canEdit} value={page.content.headline||''} onChange={e=>onUpdatePage({...page,content:{...page.content,headline:e.target.value}})} placeholder="Başlık"/><textarea disabled={!canEdit} className="field h-16 mt-2" value={page.content.body||''} onChange={e=>onUpdatePage({...page,content:{...page.content,body:e.target.value}})} placeholder="Açıklama / metin"/><select disabled={!canEdit} className="field mt-2" value={page.style?.fontFamily||fonts[0]} onChange={e=>pageStyle({fontFamily:e.target.value})}>{fonts.map(f=><option key={f}>{f}</option>)}</select><div className="grid grid-cols-2 gap-2 mt-2"><Field disabled={!canEdit} type="number" min={8} max={100} value={page.style?.fontSize||28} onChange={e=>pageStyle({fontSize:Number(e.target.value)})}/><label className="smallbox">Renk<input disabled={!canEdit} type="color" value={page.style?.backgroundColor||s.backgroundColor} onChange={e=>pageStyle({backgroundColor:e.target.value})}/></label></div><label className="flex gap-2 text-[9px] mt-2"><input disabled={!canEdit} type="checkbox" checked={page.style?.showHeader??s.showHeader} onChange={e=>pageStyle({showHeader:e.target.checked})}/> Bu sayfada üst bilgi</label><label className="flex gap-2 text-[9px] mt-2"><input disabled={!canEdit} type="checkbox" checked={page.style?.showFooter??s.showFooter} onChange={e=>pageStyle({showFooter:e.target.checked})}/> Bu sayfada alt bilgi</label></Section>}<Section title="Sayfa içi araçlar"><div className="grid grid-cols-2 gap-2"><button className="smallbtn" onClick={()=>setGrid(!grid)}><Grid3X3 size={13}/> {grid?'Grid kapat':'Grid aç'}</button><button className="smallbtn" onClick={()=>onAddBlock('text')}><Type size={13}/> Metin ekle</button><button className="smallbtn" onClick={()=>onAddBlock('image')}><ImageIcon size={13}/> Görsel çerçevesi</button><button className="smallbtn" onClick={()=>onAddBlock('product')}><Package size={13}/> Ürün çerçevesi</button></div></Section></div>}
function LayoutPanel({page,onApply}:{page:Page;onApply:(id:LayoutId)=>void}){return <div className="p-5"><Section title="Layout kütüphanesi"><p className="text-[9px] opacity-50 mb-3">Şablon görselleri sadece kompozisyonu anlatır. Gerçek ürün/görseller sayfaya uygulandığında seçili içerikten gelir. Layout seçimi Eleman sekmesine otomatik geçmez.</p><div className="grid grid-cols-2 gap-3">{layouts.map(id=><button key={id} onClick={()=>onApply(id)} className={cn('p-2 border rounded text-left',page.layoutId===id?'border-[#0f203a] bg-[#f3f5f7]':'border-[#0f203a]/10')}><div className="aspect-[1.45] overflow-hidden"><TemplatePreview id={id}/></div><div className="flex justify-between mt-2"><span className="text-[8px] font-semibold">{layoutNames[id]}</span>{page.layoutId===id&&<Check size={12}/>}</div></button>)}</div></Section></div>}
function ElementPanel({page,blockId,products,canEdit,onPatch,onRemove,onUpload,onAddBlock}:{page:Page;blockId:string|null;products:Product[];canEdit:boolean;onPatch:(p:Partial<PageBlock>)=>void;onRemove:(id:string)=>void;onUpload:(f:File)=>Promise<void>;onAddBlock:(k:'product'|'image'|'text')=>void}){const b=page.content.blocks?.find(x=>x.id===blockId);if(!b)return <div className="p-8 text-center opacity-30">Bir eleman seç.</div>;const info={...infoDefaults,...b.productInfo};return <div className="p-5"><Section title="Çerçeve / eleman"><div className="grid grid-cols-3 gap-1"><button className="smallbtn" onClick={()=>onAddBlock('product')}><Package size={12}/> Ürün</button><button className="smallbtn" onClick={()=>onAddBlock('image')}><ImageIcon size={12}/> Görsel</button><button className="smallbtn" onClick={()=>onAddBlock('text')}><Type size={12}/> Metin</button></div></Section><Section title="Konum ve boyut"><div className="grid grid-cols-4 gap-1">{(['x','y','width','height'] as const).map(k=><label key={k} className="text-[7px] uppercase">{k}<Field disabled={!canEdit} type="number" min={0} max={100} value={b[k]??10} onChange={e=>onPatch({[k]:Number(e.target.value)})}/></label>)}</div></Section>{(b.type==='frame'||b.type==='image')&&<><Section title="İçerik"><div className="flex gap-2">{b.type==='frame'&&b.frameKind==='product'?<select disabled={!canEdit} className="field" value={b.productId||''} onChange={e=>onPatch({productId:e.target.value})}><option value="">Ürün seçiniz</option>{products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select>:<label className="smallbtn flex-1 cursor-pointer"><ImageIcon size={13}/> Görsel seçiniz<input disabled={!canEdit} type="file" accept="image/*" className="hidden" onChange={async e=>{const f=e.target.files?.[0];if(f)await onUpload(f);e.target.value=''}}/></label>}</div><p className="text-[8px] opacity-40 mt-2">Çift tık sonrası iç görseli ayrı konumlandır. Ölçek küçültme/büyütme ve X/Y ayarı aşağıdadır.</p></Section><Section title="İç görsel ölçeği / konumu"><input disabled={!canEdit} type="range" min="0.5" max="3" step=".01" value={b.imageScale||1} onChange={e=>onPatch({imageScale:Number(e.target.value)})} className="w-full"/><div className="grid grid-cols-3 gap-2 mt-2"><Field disabled={!canEdit} type="number" min={0} max={100} value={b.imagePositionX??50} onChange={e=>onPatch({imagePositionX:Number(e.target.value)})}/><Field disabled={!canEdit} type="number" min={0} max={100} value={b.imagePositionY??50} onChange={e=>onPatch({imagePositionY:Number(e.target.value)})}/><select disabled={!canEdit} className="field" value={b.objectFit||'contain'} onChange={e=>onPatch({objectFit:e.target.value as any})}><option value="contain">Contain</option><option value="cover">Cover</option></select></div></Section><Section title="Çerçeve görünümü"><div className="grid grid-cols-2 gap-2"><Field disabled={!canEdit} type="number" min={0} max={8} value={b.borderWidth??1} onChange={e=>onPatch({borderWidth:Number(e.target.value)})}/><Field disabled={!canEdit} type="number" min={0} max={40} value={b.borderRadius??0} onChange={e=>onPatch({borderRadius:Number(e.target.value)})}/></div></Section><Section title="Link / QR"><Field disabled={!canEdit} value={b.linkUrl||''} onChange={e=>onPatch({linkUrl:e.target.value})} placeholder="https://..."/><label className="flex gap-2 items-center text-[9px] mt-2"><input disabled={!canEdit} type="checkbox" checked={!!b.showQr} onChange={e=>onPatch({showQr:e.target.checked})}/><QrCode size={13}/> QR otomatik oluştur</label></Section></>}{b.type==='frame'&&b.frameKind==='product'&&<ProductInfoPanel info={info} disabled={!canEdit} onChange={productInfo=>onPatch({productInfo})}/>} {b.type==='text'&&<Section title="Metin / font"><textarea disabled={!canEdit} className="field h-20" value={b.alt||''} onChange={e=>onPatch({alt:e.target.value})}/><div className="grid grid-cols-2 gap-2 mt-2"><select disabled={!canEdit} className="field" value={b.fontFamily||fonts[0]} onChange={e=>onPatch({fontFamily:e.target.value})}>{fonts.map(f=><option key={f}>{f}</option>)}</select><Field disabled={!canEdit} type="number" min={8} max={120} value={b.fontSize||24} onChange={e=>onPatch({fontSize:Number(e.target.value)})}/></div><div className="grid grid-cols-3 gap-1 mt-2"><button className="smallbtn" onClick={()=>onPatch({textAlign:'left'})}><AlignLeft size={12}/></button><button className="smallbtn" onClick={()=>onPatch({textAlign:'center'})}><AlignCenter size={12}/></button><button className="smallbtn" onClick={()=>onPatch({textAlign:'right'})}><AlignRight size={12}/></button></div></Section>}<button disabled={!canEdit} onClick={()=>onRemove(b.id)} className="w-full py-2 text-[9px] border border-red-200 text-red-600">Elemanı sil</button></div>}
function ProductInfoPanel({info,disabled,onChange}:{info:ProductInfoSettings;disabled:boolean;onChange:(x:ProductInfoSettings)=>void}){const set=(x:Partial<ProductInfoSettings>)=>onChange({...info,...x});return <Section title="Ürün bilgilerinin yerleşimi"><div className="grid grid-cols-2 gap-1">{[['showName','Ürün adı'],['showSku','SKU'],['showPrice','Fiyat'],['showMaterial','Materyal'],['showCategory','Kategori'],['showDescription','Açıklama']].map(([k,n])=><label key={k} className="flex gap-1 items-center text-[8px]"><input disabled={disabled} type="checkbox" checked={!!(info as any)[k]} onChange={e=>set({[k]:e.target.checked} as any)}/>{n}</label>)}</div><div className="grid grid-cols-2 gap-2 mt-2"><select disabled={disabled} className="field" value={info.position} onChange={e=>set({position:e.target.value as any})}><option value="below">Görsel altında</option><option value="overlay">Görsel üstünde</option><option value="left">Solunda</option><option value="right">Sağında</option></select><select disabled={disabled} className="field" value={info.align} onChange={e=>set({align:e.target.value as any})}><option value="left">Sola</option><option value="center">Ortala</option><option value="right">Sağa</option></select></div><div className="grid grid-cols-2 gap-2 mt-2"><select disabled={disabled} className="field" value={info.fontFamily||fonts[5]} onChange={e=>set({fontFamily:e.target.value})}>{fonts.map(f=><option key={f}>{f}</option>)}</select><Field disabled={disabled} type="number" min={6} max={40} value={info.fontSize||10} onChange={e=>set({fontSize:Number(e.target.value)})}/></div><div className="grid grid-cols-2 gap-2 mt-2"><Field disabled={disabled} value={info.pricePrefix||'₺'} onChange={e=>set({pricePrefix:e.target.value})}/><input disabled={disabled} type="color" value={info.color||'#0f203a'} onChange={e=>set({color:e.target.value})} className="h-10 w-full border"/></div></Section>}
function ProductsPanel({page,products,collections,categories,onUpdate}:{page:Page;products:Product[];collections:{id:string;name:string}[];categories:{id:string;name:string}[];onUpdate:(p:Page)=>void}){const[q,setQ]=React.useState(''),[mode,setMode]=React.useState('all'),[filter,setFilter]=React.useState(''),[sort,setSort]=React.useState('none');const ids=page.content.productIds||[];const list=products.filter(p=>{if(mode==='collection'&&filter&&!(p.collectionNames||[]).includes(filter))return false;if(mode==='category'&&filter&&p.category!==filter&&p.categoryFullName!==filter)return false;const s=q.toLocaleLowerCase('tr-TR');if(!s)return true;if(mode==='name')return p.name.toLocaleLowerCase('tr-TR').includes(s);if(mode==='sku')return p.sku.toLocaleLowerCase('tr-TR').includes(s);if(mode==='collection')return (p.collectionNames||[]).join(' ').toLocaleLowerCase('tr-TR').includes(s);if(mode==='category')return `${p.category} ${p.categoryFullName||''}`.toLocaleLowerCase('tr-TR').includes(s);return [p.name,p.sku,p.category,p.categoryFullName,...(p.collectionNames||[])].join(' ').toLocaleLowerCase('tr-TR').includes(s)});const filtered=[...list].sort((a,b)=>sort==='none'?0:sort==='karat-asc'?(a.karat??999)-(b.karat??999):(b.karat??-1)-(a.karat??-1));const updateIds=(next:string[])=>onUpdate({...page,content:{...page.content,productIds:next}});const toggle=(id:string,on:boolean)=>updateIds(on?Array.from(new Set([...ids,id])):ids.filter(x=>x!==id));const all=()=>updateIds(Array.from(new Set([...ids,...filtered.map(p=>p.id)])));const clear=()=>updateIds(ids.filter(id=>!filtered.some(p=>p.id===id)));return <div className="p-5"><Section title="Venta Jewelry ürünleri"><div className="relative"><Search size={13} className="absolute left-2.5 top-2.5 opacity-40"/><input value={q} onChange={e=>setQ(e.target.value)} className="field pl-7" placeholder="Ürün, SKU, kategori veya koleksiyon ara"/></div><div className="grid grid-cols-2 gap-2 mt-2"><select value={mode} onChange={e=>{setMode(e.target.value);setFilter('')}} className="field"><option value="all">Tüm alanlar</option><option value="name">Ürün adına göre</option><option value="sku">SKU numarasına göre</option><option value="collection">Koleksiyona göre</option><option value="category">Kategoriye göre</option></select><select value={filter} onChange={e=>setFilter(e.target.value)} disabled={!['category','collection'].includes(mode)} className="field"><option value="">{mode==='category'?'Kategori seç':'Koleksiyon seç'}</option>{(mode==='category'?categories.map(c=>c.name):collections.map(c=>c.name)).sort((a,b)=>a.localeCompare(b,'tr')).map(x=><option key={x}>{x}</option>)}</select></div><div className="grid grid-cols-2 gap-2 mt-2"><select value={sort} onChange={e=>setSort(e.target.value)} className="field"><option value="none">Sıralama</option><option value="karat-asc">Karat düşük → yüksek</option><option value="karat-desc">Karat yüksek → düşük</option></select><div className="flex gap-1"><button onClick={all} className="smallbtn flex-1">Hepsini seç</button><button onClick={clear} className="smallbtn">Temizle</button></div></div><div className="flex justify-between mt-2 text-[8px] opacity-50"><span>{filtered.length} ürün</span><b>{ids.length} seçili</b></div></Section><div className="max-h-[65vh] overflow-y-auto space-y-1">{filtered.map(p=>{const checked=ids.includes(p.id);return <label key={p.id} className={cn('flex items-center gap-2 p-2 border rounded cursor-pointer',checked?'border-[#0f203a] bg-[#f7f9fb]':'border-transparent')}><input type="checkbox" className="sr-only" checked={checked} onChange={e=>toggle(p.id,e.target.checked)}/><span className={cn('w-4 h-4 border flex items-center justify-center',checked?'bg-[#0f203a] text-white':'')}>{checked&&<Check size={10}/>}</span>{p.images?.[0]?<img src={p.images[0]} className="w-10 h-10 object-contain bg-white"/>:<Package size={15}/>}<span className="min-w-0 text-[9px] truncate">{p.name}<small className="block opacity-45">SKU {p.sku||'—'} · {p.karat?`${p.karat} ct · `:''}{p.category}</small></span></label>})}</div></div>}
